<script setup>
import { reactive, watch } from 'vue'
const props=defineProps({open:Boolean,title:String,description:String,fields:{type:Array,default:()=>[]},errors:{type:Object,default:()=>({})},processing:Boolean,submitLabel:{type:String,default:'ثبت اطلاعات'}})
const emit=defineEmits(['close','submit'])
const values=reactive({})
const localErrors=reactive({})
watch(()=>props.open,open=>{if(!open)return;Object.keys(values).forEach(k=>delete values[k]);Object.keys(localErrors).forEach(k=>delete localErrors[k]);props.fields.forEach(f=>values[f.key]=f.value??'')},{immediate:true})
const submit=()=>{Object.keys(localErrors).forEach(k=>delete localErrors[k]);let ok=true;props.fields.forEach(f=>{const v=values[f.key];if(f.required&&(v===''||v===null||v===undefined)){localErrors[f.key]='تکمیل این فیلد الزامی است.';ok=false}else if(f.type==='number'&&v!==''&&(!Number.isFinite(Number(v))||Number(v)<Number(f.min??0)||(f.max!==undefined&&Number(v)>Number(f.max)))){localErrors[f.key]='مقدار واردشده معتبر نیست.';ok=false}});if(ok)emit('submit',{...values})}
</script>
<template><Teleport to="body"><div v-if="open" class="fixed inset-0 z-[100] flex items-center justify-center bg-slate-950/60 p-3 sm:p-5" @click.self="!processing&&emit('close')"><section role="dialog" aria-modal="true" aria-labelledby="action-dialog-title" class="max-h-[calc(100dvh-1.5rem)] w-full max-w-lg overflow-y-auto rounded-2xl bg-white p-5 shadow-2xl sm:p-6"><h2 id="action-dialog-title" class="text-lg font-black text-slate-900">{{title}}</h2><p v-if="description" class="mt-1 text-sm leading-6 text-slate-500">{{description}}</p><form class="mt-5 space-y-4" @submit.prevent="submit"><div v-for="field in fields" :key="field.key"><label :for="'action-'+field.key" class="mb-1 block text-sm font-semibold text-slate-700">{{field.label}}</label><select v-if="field.type==='select'" :id="'action-'+field.key" v-model="values[field.key]" :required="field.required" class="w-full rounded-xl border-slate-300 text-sm"><option v-for="o in field.options||[]" :key="o.value" :value="o.value">{{o.label}}</option></select><textarea v-else-if="field.type==='textarea'" :id="'action-'+field.key" v-model="values[field.key]" :required="field.required" rows="3" maxlength="2000" class="w-full rounded-xl border-slate-300 text-sm"/><input v-else :id="'action-'+field.key" v-model="values[field.key]" :type="field.type||'text'" :required="field.required" :min="field.min" :max="field.max" :step="field.step" :maxlength="field.maxlength||255" class="w-full rounded-xl border-slate-300 text-sm"/><p v-if="localErrors[field.key]||errors[field.key]" role="alert" class="mt-1 text-xs text-rose-600">{{localErrors[field.key]||errors[field.key]}}</p></div><div v-if="Object.keys(errors).length" role="alert" class="rounded-xl bg-rose-50 p-3 text-xs text-rose-700">ثبت اطلاعات با خطا روبه‌رو شد. پیام‌های بالا را بررسی کنید.</div><div class="flex flex-col-reverse gap-2 sm:flex-row"><button type="button" :disabled="processing" @click="emit('close')" class="rounded-xl bg-slate-100 px-4 py-3 text-sm font-bold text-slate-700 sm:flex-1">انصراف</button><button type="submit" :disabled="processing" class="rounded-xl bg-teal-700 px-4 py-3 text-sm font-bold text-white disabled:opacity-50 sm:flex-1">{{processing?'در حال ثبت...':submitLabel}}</button></div></form></section></div></Teleport></template>